window.CHAPTERS = [{"title": "第1章　新しい家、新しい町", "jp": "春（はる）は四月の朝、古い家の玄関（げんかん）を開（あ）けた。窓（まど）の外には明（あか）るい太陽（たいよう）が見（み）え、少（すこ）し暖（あたた）かい風（かぜ）が吹（ふ）いていた。雨（あめ）はまだ降（ふ）っていなかったが、天気予報（てんきよほう）によると、午後（ごご）から雨になるでしょう。「ここが私（わたし）の新（あたら）しい家（いえ）です」と春は言った。「大（おお）きくはないけど、便利（べんり）な場所（ばしょ）だ。駅（えき）も近（ちか）いし、大学（だいがく）にも歩（ある）いて行（い）ける。ここで新しい生活（せいかつ）を始（はじ）めよう。」部屋（へや）の中にはベッドと机（つくえ）と小（ちい）さい棚（たな）があった。机の上には一冊（いっさつ）の本（ほん）と鉛筆（えんぴつ）と消（け）しゴムがある。引（ひ）き出（だ）しには古い手紙（てがみ）と葉書（はがき）が入（はい）っていた。その中に、青い封筒（ふうとう）が一つあった。春は不思議（ふしぎ）に思（おも）って、それを開けた。中には青いノートと短（みじか）い文（ぶん）があった。「これは何だろう。誰（だれ）がここに置（お）いたのかな。」文には、こう書いてあった。「このノートを持（も）って、毎日（まいにち）一つ新しい言葉（ことば）を覚（おぼ）えなさい。言葉を覚えるだけではなく、人と話し、新しい場所へ行き、世界（せかい）を自分の目で見てください。そうすれば、いつかこのノートの意味（いみ）が分かるはずです。」春は笑（わら）った。「子供（こども）への宿題（しゅくだい）みたいだ。でも、面白（おもしろ）そうじゃないか。」朝ご飯（あさごはん）を食べてから、春は服（ふく）を着て、帽子（ぼうし）をかぶった。玄関の前で靴（くつ）をはき、「行（い）ってきます」と言って家を出た。駅まで歩く間（あいだ）、春はノートを開いて、最初（さいしょ）の言葉を書いた。**会（あ）う。**「今日は誰かに会うことができるかな。」駅に着くと、二人（ふたり）の学生（がくせい）が電車（でんしゃ）を待（ま）っていた。一人は日本人（にほんじん）で、もう一人は外国人（がいこくじん）だった。日本人の学生が春を見て言った。「はじめまして。大学生ですか？」「はい。今日からこの大学で勉強（べんきょう）します。」「私も学生です。大学はあそこですよ。いっしょに行きませんか？」「ぜひ。どうぞよろしくお願いします。」それが、春と健（けん）の最初の出会いだった。", "en": "Haru moves into a small new home in April and finds a mysterious blue notebook. The note tells Haru to learn one new word every day, talk to people, visit new places, and see the world directly. At the station, Haru meets Ken, another university student, and they go to campus together.", "focus": "だ／です, も, が, けど, から, に／へ, こと, ことができる, てください, てから, ませんか, ましょう, の, ので, たい, たことがある, ている, まで, まえに, だけ, くらい／ぐらい, まだ, もう", "sentences": [{"jp": "春（はる）は四月の朝、古い家の玄関（げんかん）を開（あ）けた。", "en": "Spring opened the front door of the old house on the morning of April."}, {"jp": "窓（まど）の外には明（あか）るい太陽（たいよう）が見（み）え、少（すこ）し暖（あたた）かい風（かぜ）が吹（ふ）いていた。", "en": "A bright sun was visible outside the window, and a slightly warmer wind was blowing."}, {"jp": "雨（あめ）はまだ降（ふ）っていなかったが、天気予報（てんきよほう）によると、午後（ごご）から雨になるでしょう。", "en": "It hadn't rained yet, but according to the weather forecast, it will start raining in the afternoon."}, {"jp": "「ここが私（わたし）の新（あたら）しい家（いえ）です」と春は言った。", "en": "“This is my new home,” Spring said."}, {"jp": "「大（おお）きくはないけど、便利（べんり）な場所（ばしょ）だ。", "en": "\"It's not big, but it's a convenient place."}, {"jp": "駅（えき）も近（ちか）いし、大学（だいがく）にも歩（ある）いて行（い）ける。", "en": "The station is also close, and you can walk to the university."}, {"jp": "ここで新しい生活（せいかつ）を始（はじ）めよう。」", "en": "Let's just start a new life."}, {"jp": "」部屋（へや）の中にはベッドと机（つくえ）と小（ちい）さい棚（たな）があった。", "en": "There was a bed, a desk, and a small shelf in the room."}, {"jp": "机の上には一冊（いっさつ）の本（ほん）と鉛筆（えんぴつ）と消（け）しゴムがある。", "en": "On the desk is a book, a pencil, and an eraser."}, {"jp": "引（ひ）き出（だ）しには古い手紙（てがみ）と葉書（はがき）が入（はい）っていた。", "en": "There were old letters and postcards in the drawer."}, {"jp": "その中に、青い封筒（ふうとう）が一つあった。", "en": "Among them was a blue envelope."}, {"jp": "春は不思議（ふしぎ）に思（おも）って、それを開けた。", "en": "Spring wondered and opened it."}, {"jp": "中には青いノートと短（みじか）い文（ぶん）があった。", "en": "There was a blue notebook and a short sentence inside."}, {"jp": "「これは何だろう。", "en": "What -- what is this?"}, {"jp": "誰（だれ）がここに置（お）いたのかな。」", "en": "I wonder who left it here. \""}, {"jp": "」文には、こう書いてあった。", "en": "In the sentence, it was written:"}, {"jp": "「このノートを持（も）って、毎日（まいにち）一つ新しい言葉（ことば）を覚（おぼ）えなさい。", "en": "“Take this notebook and learn a new word every day."}, {"jp": "言葉を覚えるだけではなく、人と話し、新しい場所へ行き、世界（せかい）を自分の目で見てください。", "en": "Don't just learn words, talk to people, go to new places, and see the world with your own eyes."}, {"jp": "そうすれば、いつかこのノートの意味（いみ）が分かるはずです。」", "en": "That way, one day you'll understand what this notebook means. ”"}, {"jp": "」春は笑（わら）った。", "en": "\"Spring laughed."}, {"jp": "「子供（こども）への宿題（しゅくだい）みたいだ。", "en": "\"It's like homework for a child."}, {"jp": "でも、面白（おもしろ）そうじゃないか。」", "en": "But it sounds interesting. \""}, {"jp": "」朝ご飯（あさごはん）を食べてから、春は服（ふく）を着て、帽子（ぼうし）をかぶった。", "en": "After breakfast, I wore clothes and a hat in the spring."}, {"jp": "玄関の前で靴（くつ）をはき、「行（い）ってきます」と言って家を出た。", "en": "He put on his shoes in front of the entrance and left the house, saying, \"I'm going.\""}, {"jp": "駅まで歩く間（あいだ）、春はノートを開いて、最初（さいしょ）の言葉を書いた。", "en": "While walking to the station, Spring opened her notebook and wrote her first words."}, {"jp": "**会（あ）う。", "en": "koko yori sekai ni itami o"}, {"jp": "**「今日は誰かに会うことができるかな。」", "en": "* * “Can I meet someone today?”"}, {"jp": "」駅に着くと、二人（ふたり）の学生（がくせい）が電車（でんしゃ）を待（ま）っていた。", "en": "When I arrived at the station, two students were waiting for the train."}, {"jp": "一人は日本人（にほんじん）で、もう一人は外国人（がいこくじん）だった。", "en": "One was a Japanese and the other was a foreigner."}, {"jp": "日本人の学生が春を見て言った。", "en": "A Japanese student looked at the spring and said."}, {"jp": "「はじめまして。", "en": "Nice to meet you. "}, {"jp": "大学生ですか？」", "en": "Are you a college student?"}, {"jp": "」「はい。", "en": "Yes"}, {"jp": "今日からこの大学で勉強（べんきょう）します。」", "en": "I'm going to study at this university from today. ”"}, {"jp": "」「私も学生です。", "en": "\"I'm a student, too."}, {"jp": "大学はあそこですよ。", "en": "The university is there."}, {"jp": "いっしょに行きませんか？」", "en": "Would you like to go with me? \""}, {"jp": "」「ぜひ。", "en": "Please give it a try!"}, {"jp": "どうぞよろしくお願いします。」", "en": "Kindest regards"}, {"jp": "」それが、春と健（けん）の最初の出会いだった。", "en": "That was the first encounter between Haru and Ken."}]}, {"title": "第2章　大学とアルバイト", "jp": "大学の教室（きょうしつ）は大きく、壁（かべ）には世界の地図（ちず）があった。先生は佐藤（さとう）先生という、話し方が丁寧（ていねい）な人だった。「今日は日本語の文法（ぶんぽう）と会話（かいわ）について勉強します」と先生がおっしゃった。「分からないことがあれば、いつでも質問（しつもん）してください。間違（まちが）えても大丈夫（だいじょうぶ）です。」春はまだ日本語を上手に話すことができなかった。漢字（かんじ）を読むのが少し難（むずか）しいし、発音（はつおん）にも自信（じしん）があまりない。けれども、勉強を続（つづ）けるつもりだった。「日本語を話せるようになるには、毎日練習したほうがいいですよ」と健が言った。「そうだね。授業（じゅぎょう）の前に予習（よしゅう）して、授業のあとで復習（ふくしゅう）しよう。」二人は図書館（としょかん）へ行き、辞書（じしょ）やテキストを使いながら文章（ぶんしょう）を作（つく）った。春は分からない漢字を鉛筆で書き、もう一度読んだ。昼休（ひるやす）みになると、春はアルバイトの面接（めんせつ）へ出かけた。駅の近くのデパートで店員（てんいん）として働（はたら）く予定だった。受付（うけつけ）の女性（じょせい）は言った。「こちらに名前と電話番号（でんわばんごう）を書いてください。仕事について、どんなことを知りたいですか？」「給料（きゅうりょう）と仕事の時間（じかん）について伺（うかが）いたいです。」「月曜日から金曜日まで、午後五時ごろからです。試験（しけん）の前は休んでもいいですが、連絡（れんらく）しないで休むのはいけません。」「分かりました。必ず連絡します。」面接の最後に、女性は「では、明日から来てください」と言った。春は頭の中で計画（けいかく）を考（かんが）えた。大学、アルバイト、勉強、そして新しい友達。全部を続けるのは簡単（かんたん）ではないかもしれない。それでも、自分で決（き）めたことだからやってみようと思（おも）った。", "en": "Haru begins university and studies Japanese grammar, kanji, and conversation with Ken. Haru is not yet confident, but decides to continue. At a department store, Haru interviews for a part-time job and learns the schedule and rules.", "focus": "", "sentences": [{"jp": "大学の教室（きょうしつ）は大きく、壁（かべ）には世界の地図（ちず）があった。", "en": "The university classroom was large, and there was a map of the world on the wall."}, {"jp": "先生は佐藤（さとう）先生という、話し方が丁寧（ていねい）な人だった。", "en": "Teacher was Sato-sensei, who spoke in a polite manner."}, {"jp": "「今日は日本語の文法（ぶんぽう）と会話（かいわ）について勉強します」と先生がおっしゃった。", "en": "\"Today I will study Japanese grammar and conversation,\" said the teacher."}, {"jp": "「分からないことがあれば、いつでも質問（しつもん）してください。", "en": "“If you have any questions, please feel free to ask."}, {"jp": "間違（まちが）えても大丈夫（だいじょうぶ）です。」", "en": "It's okay to make mistakes."}, {"jp": "」春はまだ日本語を上手に話すことができなかった。", "en": "\"Spring still couldn't speak Japanese well."}, {"jp": "漢字（かんじ）を読むのが少し難（むずか）しいし、発音（はつおん）にも自信（じしん）があまりない。", "en": "It's a little difficult to read kanji, and I don't have much confidence in pronunciation."}, {"jp": "けれども、勉強を続（つづ）けるつもりだった。", "en": "But I was going to keep studying."}, {"jp": "「日本語を話せるようになるには、毎日練習したほうがいいですよ」と健が言った。", "en": "“It's better to practice every day to be able to speak Japanese,” Ken said."}, {"jp": "「そうだね。", "en": "\"That's right."}, {"jp": "授業（じゅぎょう）の前に予習（よしゅう）して、授業のあとで復習（ふくしゅう）しよう。」", "en": "Prepare before class and review after class. ”"}, {"jp": "」二人は図書館（としょかん）へ行き、辞書（じしょ）やテキストを使いながら文章（ぶんしょう）を作（つく）った。", "en": "\"They went to the library and made sentences using dictionaries and texts."}, {"jp": "春は分からない漢字を鉛筆で書き、もう一度読んだ。", "en": "I wrote the unknown kanji in pencil and read it again."}, {"jp": "昼休（ひるやす）みになると、春はアルバイトの面接（めんせつ）へ出かけた。", "en": "During the lunch break, Spring went out to interview for a part-time job."}, {"jp": "駅の近くのデパートで店員（てんいん）として働（はたら）く予定だった。", "en": "I was going to work as a clerk at a department store near the station."}, {"jp": "受付（うけつけ）の女性（じょせい）は言った。", "en": "said the woman at the reception."}, {"jp": "「こちらに名前と電話番号（でんわばんごう）を書いてください。", "en": "“Write your name and phone number here."}, {"jp": "仕事について、どんなことを知りたいですか？」", "en": "What do you want to know about your work? ”"}, {"jp": "」「給料（きゅうりょう）と仕事の時間（じかん）について伺（うかが）いたいです。」", "en": "\"I'd like to ask you about your salary and working hours.\""}, {"jp": "」「月曜日から金曜日まで、午後五時ごろからです。", "en": "\"From Monday to Friday, from around 5pm.\""}, {"jp": "試験（しけん）の前は休んでもいいですが、連絡（れんらく）しないで休むのはいけません。」", "en": "You can rest before the exam, but you should not rest without contacting us. \""}, {"jp": "」「分かりました。", "en": "\"Alright. "}, {"jp": "必ず連絡します。」", "en": "We'll be in touch."}, {"jp": "」面接の最後に、女性は「では、明日から来てください」と言った。", "en": "At the end of the interview, the woman said, “Then come tomorrow.”"}, {"jp": "春は頭の中で計画（けいかく）を考（かんが）えた。", "en": ""}, {"jp": "大学、アルバイト、勉強、そして新しい友達。", "en": ""}, {"jp": "全部を続けるのは簡単（かんたん）ではないかもしれない。", "en": ""}, {"jp": "それでも、自分で決（き）めたことだからやってみようと思（おも）った。", "en": ""}]}, {"title": "第3章　店で起きた小さな事件", "jp": "次の日、春はアルバイトを始めた。最初はレジの使い方がよく分からなかったので、店長（てんちょう）がゆっくり説明（せつめい）してくれた。「このボタンを押してください。お客（きゃく）さんがお金を払（はら）ったら、金額を入力します。お釣（つ）りを渡（わた）すときは、間違えないでください。」「はい。気をつけます。」店の奥には服やアクセサリー、帽子、着物（きもの）などが並（なら）んでいた。値段（ねだん）が高い品物（しなもの）もあれば、安い物もある。ある外国人のお客が店員に「この二つのどちらが安いですか」と尋（たず）ねた。春は、「こちらのほうが少し安いです。二つで三千円です」と答えた。「じゃあ、これを買います。」そのお客は財布（さいふ）を出したが、お金が足（た）りなかった。「すみません。銀行へ行けば、お金を下（お）ろせます。」「近くに銀行がありますか？」「はい。あちらの通りをまっすぐ行って、信号（しんごう）を右へ曲（ま）がってください。」お客が出てから十分ほどすると、店のベルが鳴（な）り出した。店長が走ってきた。「どうしたんですか？」「誰かが小さなバッグを置いていったようです。」中には財布、電話、鍵（かぎ）、そして一枚（いちまい）の写真があった。写真には、赤い服を着た女の子が写（うつ）っていた。「落（お）とし物（もの）かもしれません。警察（けいさつ）に連絡する必要があります。」「私が交番（こうばん）へ持って行きます」と春が言った。交番では警察官が「中身を確認しましょう」と言った。名前は分からなかったが、電話番号が見つかった。電話すると、しばらくして若い女性が来た。「本当にありがとうございます。ここには私の大切な物しか入っていないと思っていました。」「いえ。無事（ぶじ）に戻ってよかったです。」女性は何度もお礼を言って帰った。その夜、青いノートに春はこう書いた。「人を助（たす）けるのは、難しくない。小さな親切（しんせつ）でも、誰かの心（こころ）を安心（あんしん）させることができる。」", "en": "Haru starts work at a department store. A customer forgets a bag containing important belongings. Haru brings it to the police, and the owner returns to retrieve it. Haru writes in the blue notebook that even small acts of kindness can reassure someone.", "focus": "", "sentences": [{"jp": "次の日、春はアルバイトを始めた。", "en": ""}, {"jp": "最初はレジの使い方がよく分からなかったので、店長（てんちょう）がゆっくり説明（せつめい）してくれた。", "en": ""}, {"jp": "「このボタンを押してください。", "en": ""}, {"jp": "お客（きゃく）さんがお金を払（はら）ったら、金額を入力します。", "en": ""}, {"jp": "お釣（つ）りを渡（わた）すときは、間違えないでください。」", "en": "Don't make a mistake when handing out your change. ”"}, {"jp": "」「はい。", "en": "Yes"}, {"jp": "気をつけます。」", "en": "I'll try"}, {"jp": "」店の奥には服やアクセサリー、帽子、着物（きもの）などが並（なら）んでいた。", "en": "At the back of the store, there were clothes, accessories, hats, kimonos, and more."}, {"jp": "値段（ねだん）が高い品物（しなもの）もあれば、安い物もある。", "en": "Some items are expensive, while others are cheap."}, {"jp": "ある外国人のお客が店員に「この二つのどちらが安いですか」と尋（たず）ねた。", "en": "A foreign customer asked the clerk, \"Which of these two is cheaper?\""}, {"jp": "春は、「こちらのほうが少し安いです。", "en": "Spring said, \"This one is a little cheaper."}, {"jp": "二つで三千円です」と答えた。", "en": "Two is 3,000 yen. \""}, {"jp": "「じゃあ、これを買います。」", "en": "\"Then, I'll buy this.\""}, {"jp": "」そのお客は財布（さいふ）を出したが、お金が足（た）りなかった。", "en": "The customer handed out his wallet, but he didn't have enough money."}, {"jp": "「すみません。", "en": "Sorry. "}, {"jp": "銀行へ行けば、お金を下（お）ろせます。」", "en": "If you go to the bank, you can put your money down. ”"}, {"jp": "」「近くに銀行がありますか？」", "en": "\"Is there a bank nearby?\""}, {"jp": "」「はい。", "en": "Yes"}, {"jp": "あちらの通りをまっすぐ行って、信号（しんごう）を右へ曲（ま）がってください。」", "en": "Go straight down that street and turn right at the traffic light. ”"}, {"jp": "」お客が出てから十分ほどすると、店のベルが鳴（な）り出した。", "en": "\"About enough after the customer left, the store bell rang."}, {"jp": "店長が走ってきた。", "en": "The manager came running."}, {"jp": "「どうしたんですか？」", "en": "How come? "}, {"jp": "」「誰かが小さなバッグを置いていったようです。」", "en": "“Looks like someone left a small bag behind.”"}, {"jp": "」中には財布、電話、鍵（かぎ）、そして一枚（いちまい）の写真があった。", "en": "Inside was a wallet, a phone, a key, and a photo."}, {"jp": "写真には、赤い服を着た女の子が写（うつ）っていた。", "en": "The photo shows a girl dressed in red."}, {"jp": "「落（お）とし物（もの）かもしれません。", "en": "\"It may be a lost item."}, {"jp": "警察（けいさつ）に連絡する必要があります。」", "en": "We need to call the police. ”"}, {"jp": "」「私が交番（こうばん）へ持って行きます」と春が言った。", "en": "\"I'll take it to the turnout,\" said Spring."}, {"jp": "交番では警察官が「中身を確認しましょう」と言った。", "en": "At the turnout, the policeman said, \"Let's check the contents.\""}, {"jp": "名前は分からなかったが、電話番号が見つかった。", "en": "I didn't get a name, but I found a phone number."}, {"jp": "電話すると、しばらくして若い女性が来た。", "en": "When I called, a young woman came after a while."}, {"jp": "「本当にありがとうございます。", "en": "We couldn't thank you enough."}, {"jp": "ここには私の大切な物しか入っていないと思っていました。」", "en": "I thought there was only my precious things in here. ”"}, {"jp": "」「いえ。", "en": "\"No not really. "}, {"jp": "無事（ぶじ）に戻ってよかったです。」", "en": "I'm glad you made it back safely. \""}, {"jp": "」女性は何度もお礼を言って帰った。", "en": "The woman thanked him many times and left."}, {"jp": "その夜、青いノートに春はこう書いた。", "en": "That night, on the blue notebook, Spring wrote:"}, {"jp": "「人を助（たす）けるのは、難しくない。", "en": "“It's not hard to help people."}, {"jp": "小さな親切（しんせつ）でも、誰かの心（こころ）を安心（あんしん）させることができる。」", "en": "Even small acts of kindness can reassure someone. ”"}, {"jp": "」", "en": "」"}]}, {"title": "第4章　雨の日の友達", "jp": "六月になると、毎日のように雨が降った。春は雨の日があまり好きではなかった。道が濡（ぬ）れるし、靴も服も汚（よご）れるからだ。それでも、大学へ行かなければならなかった。ある朝、春が駅へ急いで歩いていると、後ろから声がした。「春君、待って！」振（ふ）り返ると、健が大きな傘（かさ）を持って走ってきた。「一人で行くのは危ないじゃないか。いっしょに行こう。」「ありがとう。でも、傘は一本しかないよ。」「それでも大丈夫。二人で入れるくらい大きいから。」二人は傘をさしながら歩いた。途中で風が強くなった。道路の水たまりが深くなり、車の水が二人の足にかかった。「うわ、最悪（さいあく）だ！」と健が笑った。春も笑い出してしまった。「こんな雨の日に笑うなんて、おかしいね。」「でも、笑ったほうが気分がよくなるでしょう。」大学に着いたころには、二人とも少し濡れていた。先生は二人を見ると、「今日は随分（ずいぶん）濡れましたね。風邪をひかないようにしてください」と言った。授業が終わったあと、春は図書館に残って勉強し続けていた。健は帰ろうとしたが、春が疲れているのに気がついた。「もう休んだほうがいいよ。勉強しすぎると頭が働かなくなるよ。」「分かっているけど、明日のテストが心配なんだ。」「心配しすぎなくてもいい。君ならできるはずだ。」春は本を閉じた。「じゃあ、今日は帰ることにする。」二人が外へ出たところで、雨が急に止んだ。雲の間から明るい光が見えた。「雨が止んでよかったね。」「うん。明日もこうだといいな。」", "en": "A rainy season tests Haru’s patience. Ken shares his umbrella with Haru, and the two become closer. After studying too much for a test, Haru realizes that rest is necessary. When the rain suddenly stops, the two head home in good spirits.", "focus": "", "sentences": [{"jp": "六月になると、毎日のように雨が降った。", "en": "It rained every day in June."}, {"jp": "春は雨の日があまり好きではなかった。", "en": "I didn't like rainy days very much in the spring."}, {"jp": "道が濡（ぬ）れるし、靴も服も汚（よご）れるからだ。", "en": "The road gets wet and your shoes and clothes get dirty."}, {"jp": "それでも、大学へ行かなければならなかった。", "en": "Still, I had to go to college."}, {"jp": "ある朝、春が駅へ急いで歩いていると、後ろから声がした。", "en": "One morning, I heard a voice from behind me as spring was rushing to the station."}, {"jp": "「春君、待って！」", "en": "\"Haru-kun, wait!\""}, {"jp": "」振（ふ）り返ると、健が大きな傘（かさ）を持って走ってきた。", "en": "Looking back, Ken came running with a big umbrella."}, {"jp": "「一人で行くのは危ないじゃないか。", "en": "\"It's dangerous to go alone, isn't it?\""}, {"jp": "いっしょに行こう。」", "en": "Let's go together. \""}, {"jp": "」「ありがとう。", "en": "Thank you."}, {"jp": "でも、傘は一本しかないよ。」", "en": "But I only have one umbrella. \""}, {"jp": "」「それでも大丈夫。", "en": "\"\" Still fine."}, {"jp": "二人で入れるくらい大きいから。」", "en": "It's big enough for two people. \""}, {"jp": "」二人は傘をさしながら歩いた。", "en": "\"The two of them walked with their umbrellas."}, {"jp": "途中で風が強くなった。", "en": "The wind got stronger on the way."}, {"jp": "道路の水たまりが深くなり、車の水が二人の足にかかった。", "en": "The puddle of water on the road became deep, and the water of the car fell on the feet of both of them."}, {"jp": "「うわ、最悪（さいあく）だ！」", "en": "\"Wow, that sucks!\""}, {"jp": "」と健が笑った。", "en": "\"Ken laughed."}, {"jp": "春も笑い出してしまった。", "en": "Spring started laughing too."}, {"jp": "「こんな雨の日に笑うなんて、おかしいね。」", "en": "“It's weird to laugh on a rainy day like this.”"}, {"jp": "」「でも、笑ったほうが気分がよくなるでしょう。」", "en": "“But laughing will make you feel better.”"}, {"jp": "」大学に着いたころには、二人とも少し濡れていた。", "en": "By the time they got to college, they were both a little wet."}, {"jp": "先生は二人を見ると、「今日は随分（ずいぶん）濡れましたね。", "en": "The teacher looked at them and said, \"You're pretty wet today, aren't you?"}, {"jp": "風邪をひかないようにしてください」と言った。", "en": "Please don't catch a cold. \""}, {"jp": "授業が終わったあと、春は図書館に残って勉強し続けていた。", "en": "After class, I stayed in the library and continued to study in the spring."}, {"jp": "健は帰ろうとしたが、春が疲れているのに気がついた。", "en": "Ken tried to go home, but he noticed that Spring was tired."}, {"jp": "「もう休んだほうがいいよ。", "en": "\"You should rest now.\""}, {"jp": "勉強しすぎると頭が働かなくなるよ。」", "en": "If you study too much, your mind will stop working. \""}, {"jp": "」「分かっているけど、明日のテストが心配なんだ。」", "en": "\"I know, but I'm worried about tomorrow's test.\""}, {"jp": "」「心配しすぎなくてもいい。", "en": "\"Don't worry too much."}, {"jp": "君ならできるはずだ。」", "en": "You'll be able to afford it."}, {"jp": "」春は本を閉じた。", "en": "Spring closed the book."}, {"jp": "「じゃあ、今日は帰ることにする。」", "en": "\"Then, I'll go home today.\""}, {"jp": "」二人が外へ出たところで、雨が急に止んだ。", "en": "\"As soon as the two of them went out, the rain stopped suddenly."}, {"jp": "雲の間から明るい光が見えた。", "en": "I saw a bright light from among the clouds."}, {"jp": "「雨が止んでよかったね。」", "en": "\"I'm glad it stopped raining.\""}, {"jp": "」「うん。", "en": "Yes. "}, {"jp": "明日もこうだといいな。」", "en": "I hope it will be like this again tomorrow. \""}, {"jp": "」", "en": "」"}]}, {"title": "第5章　地震（じしん）の夜", "jp": "夏のある夜、春は台所で晩ご飯（ばんごはん）を作っていた。電子レンジでご飯を温め、味噌汁（みそしる）を作り、野菜（やさい）と牛肉（ぎゅうにく）を焼いていた。テレビではニュース番組（ばんぐみ）が始まった。突然、テーブルが揺れた。「え？」次の瞬間、大きな地震が来た。電灯（でんとう）が消え、棚の上の箱が落ちた。ドアが鳴り、窓がガタガタした。春はすぐに火を止め、机の下に入った。怖（こわ）がって立とうとしたが、青いノートを持っていることに気がついた。「落ち着かなければいけない。慌（あわ）てて外へ出てはいけない。」地震が終わったところで、電話が鳴った。健からだった。「春、大丈夫かい？」「大丈夫。そっちは？」「僕も大丈夫。でも、近くの建物が少し壊（こわ）れたらしい。念（ねん）のため、避難（ひなん）したほうがいいかもしれない。」二人は連絡を取りながら、安全な場所へ移動（いどう）した。周りには五人ほどの学生がいた。ある人は泣いていて、ある人は電話しながら家族に知らせていた。「みんな、ここは安全です」と健が言った。「外へ出る場合は、頭を守ってください。」少しして、警察と消防（しょうぼう）の人が来た。けがをした人がいたので、看護師（かんごし）が病院へ運んだ。春は水とタオルを配（くば）り、子供たちを安心させようとした。朝になって、ニュースで被害（ひがい）の状況が放送された。多くの家では電気がまだ戻っていなかった。春はノートを開いた。「怖い経験だった。でも、困ったときには、一人で全部を解決しなくてもいい。人と助け合（たす）えばいい。」", "en": "An earthquake hits Haru’s home while Haru is cooking dinner. Haru stays calm, calls Ken, and helps others move to safety. After the earthquake, Haru writes that difficult experiences are easier to face when people help one another.", "focus": "", "sentences": [{"jp": "夏のある夜、春は台所で晩ご飯（ばんごはん）を作っていた。", "en": "One summer night, Spring was cooking dinner in the kitchen."}, {"jp": "電子レンジでご飯を温め、味噌汁（みそしる）を作り、野菜（やさい）と牛肉（ぎゅうにく）を焼いていた。", "en": "Heated the rice in a microwave, made miso soup, and baked vegetables and beef."}, {"jp": "テレビではニュース番組（ばんぐみ）が始まった。", "en": "A newscast began on television."}, {"jp": "突然、テーブルが揺れた。", "en": "Suddenly, the table shook."}, {"jp": "「え？」", "en": "“Huh?”"}, {"jp": "」次の瞬間、大きな地震が来た。", "en": "The next moment, a big earthquake came."}, {"jp": "電灯（でんとう）が消え、棚の上の箱が落ちた。", "en": "The lights went out and the box on the shelf fell."}, {"jp": "ドアが鳴り、窓がガタガタした。", "en": "The door rang and the window rattled."}, {"jp": "春はすぐに火を止め、机の下に入った。", "en": "Spring quickly turned off the fire and went under the desk."}, {"jp": "怖（こわ）がって立とうとしたが、青いノートを持っていることに気がついた。", "en": "I was scared and tried to stand up, but I noticed that he had a blue notebook."}, {"jp": "「落ち着かなければいけない。", "en": "\"We have to calm down."}, {"jp": "慌（あわ）てて外へ出てはいけない。」", "en": "Don't rush out. ”"}, {"jp": "」地震が終わったところで、電話が鳴った。", "en": "\"When the earthquake was over, the phone rang."}, {"jp": "健からだった。", "en": "It was Ken."}, {"jp": "「春、大丈夫かい？」", "en": "\"Haru, are you okay?\""}, {"jp": "」「大丈夫。", "en": "He’s ok. "}, {"jp": "そっちは？」", "en": "That way is ──\""}, {"jp": "」「僕も大丈夫。", "en": "\"I'm fine, too."}, {"jp": "でも、近くの建物が少し壊（こわ）れたらしい。", "en": "But the nearby building seems to have broken down a little."}, {"jp": "念（ねん）のため、避難（ひなん）したほうがいいかもしれない。」", "en": "You might want to evacuate just in case. \""}, {"jp": "」二人は連絡を取りながら、安全な場所へ移動（いどう）した。", "en": "\"They contacted each other and moved to a safe place."}, {"jp": "周りには五人ほどの学生がいた。", "en": "There were about five students around."}, {"jp": "ある人は泣いていて、ある人は電話しながら家族に知らせていた。", "en": "Someone was crying, and someone was calling to let the family know."}, {"jp": "「みんな、ここは安全です」と健が言った。", "en": "“Everyone, it's safe here,” Ken said."}, {"jp": "「外へ出る場合は、頭を守ってください。」", "en": "“Protect your head when you go outside.”"}, {"jp": "」少しして、警察と消防（しょうぼう）の人が来た。", "en": "Shortly after, police and firefighters arrived."}, {"jp": "けがをした人がいたので、看護師（かんごし）が病院へ運んだ。", "en": "Someone was injured, so the nurse took them to the hospital."}, {"jp": "春は水とタオルを配（くば）り、子供たちを安心させようとした。", "en": "Spring handed out water and towels to reassure the children."}, {"jp": "朝になって、ニュースで被害（ひがい）の状況が放送された。", "en": "In the morning, the damage situation was broadcast on the news."}, {"jp": "多くの家では電気がまだ戻っていなかった。", "en": "In many homes, the electricity had not yet returned."}, {"jp": "春はノートを開いた。", "en": "Spring opened the notebook."}, {"jp": "「怖い経験だった。", "en": "\"It was a scary experience."}, {"jp": "でも、困ったときには、一人で全部を解決しなくてもいい。", "en": "But when you're in trouble, you don't have to solve it all by yourself."}, {"jp": "人と助け合（たす）えばいい。」", "en": "You just have to help each other. \""}, {"jp": "」", "en": "」"}]}, {"title": "第6章　病院への道", "jp": "地震の翌日、春は大学へ行く途中で、足を痛（いた）めた学生を見つけた。階段で転（ころ）んだらしい。「大丈夫ですか？」「少し痛いですが、大丈夫です。」春は病院へ連れて行くことにした。病院までの道は近かったが、学生は歩きにくそうだった。「無理をしないでください。タクシーを呼びましょう。」病院では受付の人が「こちらでお待ちください」と言った。看護師が来て、学生の足を確認した。「骨には問題がないようです。ですが、今日は十分休んだほうがいいでしょう。」医者も「明日までに痛みがなくなれば、大学へ行ってもいいです」と説明した。春は安心した。帰ろうとしたとき、看護師が「親切に連れてきてくれてありがとうございます」と言った。「いえ、困っている人を見たら助けるべきだと思います。」病院を出ると、春は健に電話した。「今日は大学に行かないかもしれない。病院へ行っていたんだ。」「そうだったのか。体に気をつけて。今夜は早く寝たほうがいいよ。」帰宅してから、春は服を脱ぎ、手を洗い、温かい牛乳を一杯飲んだ。布団（ふとん）を敷いて横になると、急に眠くなった。「最近、忙しすぎるみたいだ。もっと休むようにしよう。」その夜は深く眠った。", "en": "Haru finds an injured student and takes them to a hospital. The injury is not serious, and the doctor recommends rest. Haru realizes that life has been too busy and decides to make more time for sleep.", "focus": "", "sentences": [{"jp": "地震の翌日、春は大学へ行く途中で、足を痛（いた）めた学生を見つけた。", "en": "The day after the earthquake, Spring was on her way to college when she found a student with a broken leg."}, {"jp": "階段で転（ころ）んだらしい。", "en": "He fell down the stairs."}, {"jp": "「大丈夫ですか？」", "en": "“Are you guy ok?”"}, {"jp": "」「少し痛いですが、大丈夫です。」", "en": "\"It hurts a little, but it's okay.\""}, {"jp": "」春は病院へ連れて行くことにした。", "en": "\"Spring decided to take her to the hospital."}, {"jp": "病院までの道は近かったが、学生は歩きにくそうだった。", "en": "The road to the hospital was close, but the students seemed to be difficult to walk."}, {"jp": "「無理をしないでください。", "en": "\"Please don't overdo it."}, {"jp": "タクシーを呼びましょう。」", "en": "Let's call a taxi. ”"}, {"jp": "」病院では受付の人が「こちらでお待ちください」と言った。", "en": "At the hospital, the receptionist said, \"Please wait here.\""}, {"jp": "看護師が来て、学生の足を確認した。", "en": "A nurse came and checked the student's feet."}, {"jp": "「骨には問題がないようです。", "en": "\"There seems to be no problem with the bones."}, {"jp": "ですが、今日は十分休んだほうがいいでしょう。」", "en": "But you'd better get some rest today. ”"}, {"jp": "」医者も「明日までに痛みがなくなれば、大学へ行ってもいいです」と説明した。", "en": "The doctor also explained, \"If the pain goes away by tomorrow, you can go to college.\""}, {"jp": "春は安心した。", "en": "I was relieved in the spring."}, {"jp": "帰ろうとしたとき、看護師が「親切に連れてきてくれてありがとうございます」と言った。", "en": "When I tried to go home, the nurse said, “Thank you for your kindness in bringing me here.”"}, {"jp": "「いえ、困っている人を見たら助けるべきだと思います。」", "en": "“No, I think we should help people who are in need.”"}, {"jp": "」病院を出ると、春は健に電話した。", "en": "When I left the hospital, Spring called Ken."}, {"jp": "「今日は大学に行かないかもしれない。", "en": "\"I might not go to college today."}, {"jp": "病院へ行っていたんだ。」", "en": "I was at the hospital. \""}, {"jp": "」「そうだったのか。", "en": "\"Really, so that's how it was done/I see."}, {"jp": "体に気をつけて。", "en": "Take care."}, {"jp": "今夜は早く寝たほうがいいよ。」", "en": "You should go to bed early tonight. \""}, {"jp": "」帰宅してから、春は服を脱ぎ、手を洗い、温かい牛乳を一杯飲んだ。", "en": "When I got home, I took off my clothes, washed my hands, and drank a glass of warm milk in the spring."}, {"jp": "布団（ふとん）を敷いて横になると、急に眠くなった。", "en": "When I lay down on the futon, I suddenly felt sleepy."}, {"jp": "「最近、忙しすぎるみたいだ。", "en": "\"Looks like I've been too busy lately.\""}, {"jp": "もっと休むようにしよう。」", "en": "Let's get some rest. \""}, {"jp": "」その夜は深く眠った。", "en": "That night, I slept deeply."}]}, {"title": "第7章　京都への旅行", "jp": "秋になった。大学の授業が少なくなった週末、健が春に電話した。「京都（きょうと）へ旅行しないか？」「いいね。前から行きたいと思っていた。」「じゃあ、土曜日の朝八時ごろ駅で会おう。切符（きっぷ）はもう買っておいたよ。」土曜日、二人は特急（とっきゅう）に乗った。途中の駅で別の電車に乗り換えた。窓から山や川、町の景色（けしき）が見えた。「この景色は写真みたいだね。」「本当だ。日本の歴史を勉強してから見ると、町の意味が少し分かるようになってきた。」京都では古い寺と神社（じんじゃ）を見物し、旅館（りょかん）に泊まった。旅館の人は「お疲れになったでしょう。どうぞこちらへ」と二人を案内した。部屋には畳（たたみ）と布団があり、窓の外には庭があった。夕方になると空が赤くなり、静かな風が吹いた。「こんな場所に来られてよかった。」夜、旅館の人がご飯と味噌汁、魚を持ってきた。「どうぞ召（め）し上がってください。」「いただきます。」食事のあと、二人は明日の予定について話した。「明日は山へ行く？　それとも海のほうがいい？」「山と海なら、どちらが静かかな。」「山のほうが静かだと思う。でも、天気が悪ければ海へ行こう。」翌朝、天気予報を見てから山へ向かった。途中で小鳥（ことり）の声が聞こえた。秋の葉が風に揺れ、古い道が森の中へ続いていた。春は青いノートに一文を書いた。「旅をするということは、知らない場所を見るだけではない。自分の考え方も変えていくことだ。」", "en": "Haru and Ken travel to Kyoto. They ride trains, stay at a traditional inn, eat Japanese food, and explore historic places. Haru realizes that traveling can change the way a person thinks, not just expose them to new places.", "focus": "", "sentences": [{"jp": "秋になった。", "en": "It's autumn."}, {"jp": "大学の授業が少なくなった週末、健が春に電話した。", "en": "Ken called in the spring on a weekend when there were fewer classes at the university."}, {"jp": "「京都（きょうと）へ旅行しないか？」", "en": "\"Would you like to travel to Kyoto?\""}, {"jp": "」「いいね。", "en": "Ah, good."}, {"jp": "前から行きたいと思っていた。」", "en": "I've always wanted to go. ”"}, {"jp": "」「じゃあ、土曜日の朝八時ごろ駅で会おう。", "en": "\"Then, I'll see you at the station around 8 o'clock on Saturday morning.\""}, {"jp": "切符（きっぷ）はもう買っておいたよ。」", "en": "I already bought a ticket. \""}, {"jp": "」土曜日、二人は特急（とっきゅう）に乗った。", "en": "\"On Saturday, the two of them got on the limited express."}, {"jp": "途中の駅で別の電車に乗り換えた。", "en": "I switched to another train at the station on the way."}, {"jp": "窓から山や川、町の景色（けしき）が見えた。", "en": "I could see the mountains, the river, and the view of the town from the window."}, {"jp": "「この景色は写真みたいだね。」", "en": "\"This scenery looks like a picture.\""}, {"jp": "」「本当だ。", "en": "Now they are."}, {"jp": "日本の歴史を勉強してから見ると、町の意味が少し分かるようになってきた。」", "en": "After studying Japanese history, I began to understand the meaning of the town a little. \""}, {"jp": "」京都では古い寺と神社（じんじゃ）を見物し、旅館（りょかん）に泊まった。", "en": "\"In Kyoto, I visited old temples and shrines and stayed at a ryokan."}, {"jp": "旅館の人は「お疲れになったでしょう。", "en": "The innkeeper said, \"You must be tired."}, {"jp": "どうぞこちらへ」と二人を案内した。", "en": "Please come this way, \"he said to the two of them."}, {"jp": "部屋には畳（たたみ）と布団があり、窓の外には庭があった。", "en": "There were tatami mats and futons in the room, and a garden outside the window."}, {"jp": "夕方になると空が赤くなり、静かな風が吹いた。", "en": "In the evening, the sky turned red and a quiet breeze blew."}, {"jp": "「こんな場所に来られてよかった。」", "en": "“I'm glad you came to this place.”"}, {"jp": "」夜、旅館の人がご飯と味噌汁、魚を持ってきた。", "en": "\"At night, the inn people brought rice, miso soup, and fish."}, {"jp": "「どうぞ召（め）し上がってください。」", "en": "\"Please enjoy your meal. "}, {"jp": "」「いただきます。」", "en": "Let's eat!"}, {"jp": "」食事のあと、二人は明日の予定について話した。", "en": "After the meal, the two talked about their plans for tomorrow."}, {"jp": "「明日は山へ行く？", "en": "\"Are you going to the mountains tomorrow?\""}, {"jp": "それとも海のほうがいい？」", "en": "Or do you prefer the sea? \""}, {"jp": "」「山と海なら、どちらが静かかな。」", "en": "\"If it's the mountains or the sea, which is quieter?\""}, {"jp": "」「山のほうが静かだと思う。", "en": "\"I think the mountain is quieter."}, {"jp": "でも、天気が悪ければ海へ行こう。」", "en": "But if the weather is bad, let's go to the sea. \""}, {"jp": "」翌朝、天気予報を見てから山へ向かった。", "en": "The next morning, I watched the weather forecast and then headed for the mountains."}, {"jp": "途中で小鳥（ことり）の声が聞こえた。", "en": "I heard a bird on the way."}, {"jp": "秋の葉が風に揺れ、古い道が森の中へ続いていた。", "en": "The autumn leaves were swaying in the wind, and the old road led into the forest."}, {"jp": "春は青いノートに一文を書いた。", "en": "Spring wrote a sentence on the blue notebook."}, {"jp": "「旅をするということは、知らない場所を見るだけではない。", "en": "“Traveling doesn't just mean looking at places you don't know."}, {"jp": "自分の考え方も変えていくことだ。」", "en": "It's about changing the way you think. ”"}, {"jp": "」", "en": "」"}]}, {"title": "第8章　研究室の計画", "jp": "冬になる前に、春は大学の研究室（けんきゅうしつ）で研究（けんきゅう）を始めた。テーマは「外国人（がいこくじん）が日本の文化（ぶんか）をどのように学ぶか」だった。先生は「研究を行うためには、資料（しりょう）を集める必要があります」と説明した。「本を読むだけではなく、実際（じっさい）に人の話を聞いてください。」春は外国人学生や市民（しみん）に質問し、会議室（かいぎしつ）でメモを取った。質問には、「日本での生活で困ることは何ですか」「どんな文化の違（ちが）いに気がつきましたか」などがあった。ある学生は「電車は便利ですが、説明が難しいです」と言った。別の学生は「ルールが多すぎるように感じます」と答えた。春は意見を比（くら）べながら、原因を考えた。「言葉の問題だけではない。社会、教育、交通、仕事など、いろいろな関係があるのかもしれない。」調査（ちょうさ）が続くにつれて、春は研究のやり方がだんだん分かるようになった。最初は質問するのが苦手だったが、今では相手に合わせて話すことができる。先生はある日、研究ノートを見て言った。「春さん、よくできています。あなたは人の話を聞くのが上手になりましたね。」「ありがとうございます。先生に教えていただいたおかげです。」先生は笑った。「明日までにこの結果をまとめていただけませんか？」「はい、承知しました。」その夜、春は遅くまで研究を続けた。眠いながらも文章を書き、表を作り、データを整理した。最後に「もう十分だ」と思って保存した。しかし、次の朝、パソコンを開くとファイルがなかった。「しまった。保存する前にパソコンが止まったかもしれない！」春は青くなった。", "en": "Haru begins a university research project on how foreigners learn Japanese culture. Interviews reveal that language is only one part of the difficulty. Haru improves at interviewing, but accidentally loses a file after working late.", "focus": "", "sentences": [{"jp": "冬になる前に、春は大学の研究室（けんきゅうしつ）で研究（けんきゅう）を始めた。", "en": "Before winter, Spring started researching in the university lab."}, {"jp": "テーマは「外国人（がいこくじん）が日本の文化（ぶんか）をどのように学ぶか」だった。", "en": "The theme was \"How foreigners learn about Japanese culture\"."}, {"jp": "先生は「研究を行うためには、資料（しりょう）を集める必要があります」と説明した。", "en": "The teacher explained, \"In order to conduct research, we need to collect materials.\""}, {"jp": "「本を読むだけではなく、実際（じっさい）に人の話を聞いてください。」", "en": "“Don't just read books, listen to people.”"}, {"jp": "」春は外国人学生や市民（しみん）に質問し、会議室（かいぎしつ）でメモを取った。", "en": "Spring asked foreign students and citizens questions and took notes in the conference room."}, {"jp": "質問には、「日本での生活で困ることは何ですか」「どんな文化の違（ちが）いに気がつきましたか」などがあった。", "en": "Questions included \"What are the troubles of living in Japan?\" and \"What cultural differences did you notice?\""}, {"jp": "ある学生は「電車は便利ですが、説明が難しいです」と言った。", "en": "One student said, “The train is convenient, but difficult to explain.”"}, {"jp": "別の学生は「ルールが多すぎるように感じます」と答えた。", "en": "Another student replied, “I feel like there are too many rules.”"}, {"jp": "春は意見を比（くら）べながら、原因を考えた。", "en": "Haru considered the cause while comparing his opinions."}, {"jp": "「言葉の問題だけではない。", "en": "\"It's not just a matter of words."}, {"jp": "社会、教育、交通、仕事など、いろいろな関係があるのかもしれない。」", "en": "There may be various relationships such as society, education, transportation, and work. \""}, {"jp": "」調査（ちょうさ）が続くにつれて、春は研究のやり方がだんだん分かるようになった。", "en": "\"As the investigation continued, I gradually learned how to do research in the spring."}, {"jp": "最初は質問するのが苦手だったが、今では相手に合わせて話すことができる。", "en": "At first, I was not good at asking questions, but now I can talk to the other person accordingly."}, {"jp": "先生はある日、研究ノートを見て言った。", "en": "One day, the teacher looked at the research notebook and said."}, {"jp": "「春さん、よくできています。", "en": "\"Harusan, you're doing great."}, {"jp": "あなたは人の話を聞くのが上手になりましたね。」", "en": "You're a good listener. ”"}, {"jp": "」「ありがとうございます。", "en": "Thanks!"}, {"jp": "先生に教えていただいたおかげです。」", "en": "Thank you for teaching me. \""}, {"jp": "」先生は笑った。", "en": "\"The teacher laughed."}, {"jp": "「明日までにこの結果をまとめていただけませんか？」", "en": "“Can you summarize these results by tomorrow?”"}, {"jp": "」「はい、承知しました。」", "en": "Yes I'm sure"}, {"jp": "」その夜、春は遅くまで研究を続けた。", "en": "That night, I continued my research until late in the spring."}, {"jp": "眠いながらも文章を書き、表を作り、データを整理した。", "en": "While sleeping, I wrote sentences, created tables, and organized data."}, {"jp": "最後に「もう十分だ」と思って保存した。", "en": "Finally, I saved it thinking, \"Enough is enough.\""}, {"jp": "しかし、次の朝、パソコンを開くとファイルがなかった。", "en": "However, the next morning, when I opened my computer, there were no files."}, {"jp": "「しまった。", "en": "America."}, {"jp": "保存する前にパソコンが止まったかもしれない！」", "en": "My computer may have stopped before I saved it! \""}, {"jp": "」春は青くなった。", "en": "\"Spring has turned blue."}]}, {"title": "第9章　青いノートの秘密", "jp": "春はなくなったファイルを探して、研究室の中を何度も見た。机の下、棚の中、引き出し、パソコンの周り。何もない。「これは困った。昨日のデータは全部必要だ。」そのとき、机の奥から青い光が見えた。青いノートだった。ノートを開くと、最初の日に書いた文が少し変わっていた。「失敗した場合は、最初から考え直すこと。」「え？　どういうこと？」ページをめくると、「データは失われたのではなく、別の場所にあるようです」と書いてあった。春は研究室の中をもう一度見た。すると、古い外付けディスクが見つかった。春が昨日の夜に使ったものだった。「もしかしたら、ここにあるかもしれない。」ディスクを確認すると、データが全部残っていた。「助かった！」健に電話すると、健は「それでも、バックアップは必要だよ。大事なファイルなら、二つ以上の場所に保存しておいたほうがいい」と言った。春はうなずいた。「その通りだ。これからは大切なデータを必ず保存するようにする。」夜、春は青いノートの最初のページをじっと見た。そこには、古い字で「会う」と書いてあるだけだった。「このノートは、言葉を覚えるためだけのものじゃない。」その瞬間、春は最初から起きていたことを思い出した。新しい家、健との出会い、店での事件、地震、病院、京都、研究。そして、その全部で自分の日本語が少しずつ変わっていた。「言葉を学ぶということは、人との関係を学ぶことでもあるんだ。」", "en": "Haru discovers that the lost research file is actually backed up on an old external disk. The blue notebook then reveals its real purpose: it was never just a vocabulary notebook. It has been guiding Haru toward understanding that language is connected to relationships and experience.", "focus": "", "sentences": [{"jp": "春はなくなったファイルを探して、研究室の中を何度も見た。", "en": "I searched the lab for the missing files in the spring and saw them again and again."}, {"jp": "机の下、棚の中、引き出し、パソコンの周り。", "en": "Under the desk, on the shelf, in the drawer, around the computer."}, {"jp": "何もない。", "en": " [Bill] Nothing."}, {"jp": "「これは困った。", "en": "\"This is troublesome."}, {"jp": "昨日のデータは全部必要だ。」", "en": "We need all the data from yesterday. \""}, {"jp": "」そのとき、机の奥から青い光が見えた。", "en": "At that time, I saw a blue light from the back of the desk."}, {"jp": "青いノートだった。", "en": "It was a blue notebook."}, {"jp": "ノートを開くと、最初の日に書いた文が少し変わっていた。", "en": "When I opened the notebook, the sentence I wrote on the first day was slightly different."}, {"jp": "「失敗した場合は、最初から考え直すこと。」", "en": "“If you fail, rethink from the beginning.”"}, {"jp": "」「え？", "en": "Eh? "}, {"jp": "どういうこと？」", "en": "\"What's going on?\" "}, {"jp": "」ページをめくると、「データは失われたのではなく、別の場所にあるようです」と書いてあった。", "en": "When I flipped over the page, it said, “The data doesn't seem to have been lost, it seems to be somewhere else.”"}, {"jp": "春は研究室の中をもう一度見た。", "en": "Spring looked inside the lab again."}, {"jp": "すると、古い外付けディスクが見つかった。", "en": "Then an old external disk was found."}, {"jp": "春が昨日の夜に使ったものだった。", "en": "Spring was what I used last night."}, {"jp": "「もしかしたら、ここにあるかもしれない。」", "en": "“Maybe it's here.”"}, {"jp": "」ディスクを確認すると、データが全部残っていた。", "en": "\"When I checked the disk, all the data was still there."}, {"jp": "「助かった！」", "en": "Thank God! \""}, {"jp": "」健に電話すると、健は「それでも、バックアップは必要だよ。", "en": "When I called Ken, Ken said, \"Still, you need a backup."}, {"jp": "大事なファイルなら、二つ以上の場所に保存しておいたほうがいい」と言った。", "en": "If it's an important file, you should save it in two or more places. \""}, {"jp": "春はうなずいた。", "en": "Spring nodded."}, {"jp": "「その通りだ。", "en": "\"No doubt about that."}, {"jp": "これからは大切なデータを必ず保存するようにする。」", "en": "From now on, be sure to save your important data. ”"}, {"jp": "」夜、春は青いノートの最初のページをじっと見た。", "en": "\"At night, Spring stared at the first page of the blue notebook."}, {"jp": "そこには、古い字で「会う」と書いてあるだけだった。", "en": "There, it was just \"meet\" written in the old script."}, {"jp": "「このノートは、言葉を覚えるためだけのものじゃない。」", "en": "“This notebook is not just for memorizing words.”"}, {"jp": "」その瞬間、春は最初から起きていたことを思い出した。", "en": "\"At that moment, I remembered that spring had been happening from the beginning."}, {"jp": "新しい家、健との出会い、店での事件、地震、病院、京都、研究。", "en": "New house, encounter with Ken, incident at the store, earthquake, hospital, Kyoto, research."}, {"jp": "そして、その全部で自分の日本語が少しずつ変わっていた。", "en": "And in all of that, my Japanese changed little by little."}, {"jp": "「言葉を学ぶということは、人との関係を学ぶことでもあるんだ。」", "en": "“Learning to speak is also learning to relate to people.”"}, {"jp": "」", "en": "」"}]}, {"title": "第10章　家族からの手紙", "jp": "年末が近づいたころ、春の家族から手紙が届いた。父、母、姉、兄、妹、そして祖母からの短いメッセージだった。母の手紙には、「元気ですか。最近は忙しそうですが、体を大切にしてください」と書いてあった。父は、「仕事も勉強も大事だが、家族を忘れないように」と書いた。姉は、「来年はいつ帰ってくるの？」と尋ねた。春は久しぶりに家族へ電話した。「もしもし。みんな元気？」「元気だよ。お正月（しょうがつ）には帰ってくる？」と母が聞いた。「うん。帰るつもり。お土産（みやげ）も買っていくよ。」祖母は電話に出ると、「ああ、春かい。大きくなったね」と笑った。「おばあちゃん、僕はもう大学生だよ。」「分かっているよ。でも、家族にとってはまだ小さい子供みたいなものさ。」みんなが笑った。電話のあと、春はデパートへ行き、父には帽子、母にはアクセサリー、姉には本、妹には小さな玩具（おもちゃ）を選んだ。祖母には柔らかい着物の布を買った。店員に「この品物を箱に入れていただけませんか」とお願いすると、「かしこまりました」と丁寧に答えてくれた。帰り道、春は「家族からもらったものは、お金では比べられない」と思った。家に戻り、「ただいま」と言うと、自分の声が少し変わって聞こえた。「おかえりなさい」と誰かが返事をしたような気がした。春は驚いて振り向いたが、部屋には誰もいなかった。ただ、青いノートが机の上で開いていた。", "en": "Haru receives letters from family and calls home. The conversation makes Haru nostalgic and reminds Haru that family relationships cannot be measured in money. Back home, Haru hears what sounds like “welcome home,” but nobody is there. The blue notebook is open again.", "focus": "", "sentences": [{"jp": "年末が近づいたころ、春の家族から手紙が届いた。", "en": "As the end of the year approached, I received a letter from my spring family."}, {"jp": "父、母、姉、兄、妹、そして祖母からの短いメッセージだった。", "en": "It was a short message from my father, mother, sister, brother, sister, and grandmother."}, {"jp": "母の手紙には、「元気ですか。", "en": "My mother's letter said, \"How are you?"}, {"jp": "最近は忙しそうですが、体を大切にしてください」と書いてあった。", "en": "I seem to be busy these days, but please take care of your body. \""}, {"jp": "父は、「仕事も勉強も大事だが、家族を忘れないように」と書いた。", "en": "My father wrote, \"Work and study are important, but don't forget your family.\""}, {"jp": "姉は、「来年はいつ帰ってくるの？」", "en": "My sister asked, “When are you coming back next year?”"}, {"jp": "」と尋ねた。", "en": "when we did not understand the purpose given in the answer. "}, {"jp": "春は久しぶりに家族へ電話した。", "en": "Spring hasn't called my family in a long time."}, {"jp": "「もしもし。", "en": "**Knock, knock."}, {"jp": "みんな元気？」", "en": "Everybody's Fine"}, {"jp": "」「元気だよ。", "en": "I&apos;m fine."}, {"jp": "お正月（しょうがつ）には帰ってくる？」", "en": "Are you coming back for the New Year? \""}, {"jp": "」と母が聞いた。", "en": "\"My mother asked."}, {"jp": "「うん。", "en": "\"Yup. "}, {"jp": "帰るつもり。", "en": "I'm leaving."}, {"jp": "お土産（みやげ）も買っていくよ。」", "en": "I'll also buy souvenirs. \""}, {"jp": "」祖母は電話に出ると、「ああ、春かい。", "en": "Grandma answered the phone and said, \"Oh, spring."}, {"jp": "大きくなったね」と笑った。", "en": "You've grown up, ”he laughed."}, {"jp": "「おばあちゃん、僕はもう大学生だよ。」", "en": "\"Grandma, I'm already a college student.\""}, {"jp": "」「分かっているよ。", "en": "I don't wanna leave you either."}, {"jp": "でも、家族にとってはまだ小さい子供みたいなものさ。」", "en": "But for the family, it's still like a small child. \""}, {"jp": "」みんなが笑った。", "en": "Everyone laughed."}, {"jp": "電話のあと、春はデパートへ行き、父には帽子、母にはアクセサリー、姉には本、妹には小さな玩具（おもちゃ）を選んだ。", "en": "After the phone call, I went to the department store in the spring, and I chose a hat for my father, an accessory for my mother, a book for my sister, and a small toy for my sister."}, {"jp": "祖母には柔らかい着物の布を買った。", "en": "I bought my grandmother a soft kimono cloth."}, {"jp": "店員に「この品物を箱に入れていただけませんか」とお願いすると、「かしこまりました」と丁寧に答えてくれた。", "en": "I asked the clerk, \"Could you put this item in the box?\" He politely replied, \"I understand.\""}, {"jp": "帰り道、春は「家族からもらったものは、お金では比べられない」と思った。", "en": "On the way home, Spring thought, \"What I got from my family can't be compared with money.\""}, {"jp": "家に戻り、「ただいま」と言うと、自分の声が少し変わって聞こえた。", "en": "When I returned home and said, “I'm home,” I heard a slight change in my voice."}, {"jp": "「おかえりなさい」と誰かが返事をしたような気がした。", "en": "I felt like someone replied, \"Welcome back.\""}, {"jp": "春は驚いて振り向いたが、部屋には誰もいなかった。", "en": "Spring turned around in surprise, but there was no one in the room."}, {"jp": "ただ、青いノートが机の上で開いていた。", "en": "However, a blue notebook was open on the desk."}]}, {"title": "第11章　祭りの日の最後の課題", "jp": "春になり、大学では大きなお祭（まつ）りが開（ひら）かれた。学生たちは食べ物の店を出したり、音楽を演奏したり、踊（おど）ったりした。春と健は日本語学習の小さなコーナーを作った。そこでは、外国人学生が漢字を書いたり、簡単な文を作ったりすることができた。「この漢字は何と読みますか？」と参加者が聞いた。「これは『道（みち）』です。道という言葉は、実際の道だけではなく、人生の道という意味にも使えます。」その横では、「日本語の勉強は難しいけど、楽しい」と大きく書いた紙が貼ってあった。午後になると、お祭りはますます賑（にぎ）やかになった。子供たちは走り回り、小鳥が近くの木で鳴いていた。焼き肉の匂（にお）いがし、音楽が聞こえ、人々の笑い声がした。突然、一人の男の子が泣き始めた。「お母さんがいない！」春は男の子のところへ行った。「大丈夫。お母さんをいっしょに探そう。」健は受付に連絡し、放送をお願いした。しばらくすると、心配そうな女性が走ってきた。「息子（むすこ）です！」「お母さん！」二人は抱（だ）き合った。女性は「本当にありがとうございました」と何度も言った。春は笑って、「どういたしまして」と答えた。夕方、祭りが終わる前に、佐藤先生が来た。「春さん、これが最後の課題です。」先生は青いノートを指した。「このノートを最後まで読んで、自分が何を学んだか説明してください。」春はノートを開いた。最後のページには一行しかなかった。「あなたは、もう一つの言葉を知っています。」その下には、漢字が一つ書いてあった。**帰（かえ）る。**春は静かに笑った。", "en": "At the university festival, Haru helps run a Japanese-learning booth and later helps reunite a lost child with his mother. Professor Sato gives Haru one final task: read the notebook to the end and explain what Haru has learned. The final word is 帰る, “to return home.”", "focus": "", "sentences": [{"jp": "春になり、大学では大きなお祭（まつ）りが開（ひら）かれた。", "en": "In the spring, a big festival was held at the university."}, {"jp": "学生たちは食べ物の店を出したり、音楽を演奏したり、踊（おど）ったりした。", "en": "The students opened food stores, played music, and danced."}, {"jp": "春と健は日本語学習の小さなコーナーを作った。", "en": "Haru and Ken made a small corner for learning Japanese."}, {"jp": "そこでは、外国人学生が漢字を書いたり、簡単な文を作ったりすることができた。", "en": "There, foreign students were able to write kanji and write simple sentences."}, {"jp": "「この漢字は何と読みますか？」", "en": "How do you read this kanji?"}, {"jp": "」と参加者が聞いた。", "en": "\"the participant asked."}, {"jp": "「これは『道（みち）』です。", "en": "\"This is the 'road'."}, {"jp": "道という言葉は、実際の道だけではなく、人生の道という意味にも使えます。」", "en": "The word way can be used to mean not only the actual way, but also the way of life. ”"}, {"jp": "」その横では、「日本語の勉強は難しいけど、楽しい」と大きく書いた紙が貼ってあった。", "en": "Next to it, there was a large piece of paper that said, \"Learning Japanese is difficult, but it's fun.\""}, {"jp": "午後になると、お祭りはますます賑（にぎ）やかになった。", "en": "In the afternoon, the festival became more and more lively."}, {"jp": "子供たちは走り回り、小鳥が近くの木で鳴いていた。", "en": "The children were running around, and the birds were singing in the nearby trees."}, {"jp": "焼き肉の匂（にお）いがし、音楽が聞こえ、人々の笑い声がした。", "en": "I smelled yakiniku, I heard music, and people laughed."}, {"jp": "突然、一人の男の子が泣き始めた。", "en": "Suddenly, a boy began to cry."}, {"jp": "「お母さんがいない！」", "en": "\"I don't have a mother!\""}, {"jp": "」春は男の子のところへ行った。", "en": "Spring went to the boy."}, {"jp": "「大丈夫。", "en": "\"It's okay."}, {"jp": "お母さんをいっしょに探そう。」", "en": "Let's find your mom together. ”"}, {"jp": "」健は受付に連絡し、放送をお願いした。", "en": "Ken contacted the reception and asked for a broadcast."}, {"jp": "しばらくすると、心配そうな女性が走ってきた。", "en": "After a while, a worried woman came running."}, {"jp": "「息子（むすこ）です！」", "en": "Both of us."}, {"jp": "」「お母さん！」", "en": "[おかあさん] /(n) (hon) mother/(P)/"}, {"jp": "」二人は抱（だ）き合った。", "en": "The two embraced."}, {"jp": "女性は「本当にありがとうございました」と何度も言った。", "en": "The woman repeatedly said, “Thank you so much.”"}, {"jp": "春は笑って、「どういたしまして」と答えた。", "en": "Haru laughed and replied, \"You're welcome.\""}, {"jp": "夕方、祭りが終わる前に、佐藤先生が来た。", "en": "In the evening, before the festival was over, Dr. Sato came."}, {"jp": "「春さん、これが最後の課題です。」", "en": "“Haru-san, this is your last assignment.”"}, {"jp": "」先生は青いノートを指した。", "en": "\"The teacher pointed to the blue notebook."}, {"jp": "「このノートを最後まで読んで、自分が何を学んだか説明してください。」", "en": "“Read this notebook to the end and explain what you learned.”"}, {"jp": "」春はノートを開いた。", "en": "\"Spring opened the notebook."}, {"jp": "最後のページには一行しかなかった。", "en": "There was only one line on the last page."}, {"jp": "「あなたは、もう一つの言葉を知っています。」", "en": "“You know another word.”"}, {"jp": "」その下には、漢字が一つ書いてあった。", "en": "Below it, a single kanji was written."}, {"jp": "**帰（かえ）る。", "en": "I'm leaving."}, {"jp": "**春は静かに笑った。", "en": "* * Spring laughed quietly."}]}, {"title": "第12章　帰るということ", "jp": "祭りのあと、春は一人で大学の屋上（おくじょう）へ行った。町の向こうには山が見え、遠くには海も見えた。空は赤く、夕方の光がゆっくり消えていった。青いノートを開くと、今までのページが全部一つの話になっていた。「会う。話す。助ける。失敗する。考える。続ける。そして、帰る。」春は考えた。「帰るというのは、ただ家へ戻ることではないのかもしれない。」新しい場所へ出て、知らない人に会い、違う考え方を知り、失敗して、それでも前へ進む。そのあとで、自分が大切にしている場所へ戻る。そういうことも「帰る」と言ってもいいのだろう。健が屋上へ来た。「ここにいたのか。みんな春を探しているよ。」「そうなの？」「うん。もう帰ろう。」春はノートを閉じた。「健。ありがとう。君に会えてよかった。」「何だよ、急に。」「この一年で、いろいろなことを学んだから。」二人はエレベーターで下へ行き、大学の出口を通った。外では学生たちが話したり笑ったりしていた。通りには店の明かりがつき始め、駅へ向かう人が増えていた。春は立ち止まった。「最初の日、この場所がただの新しい町に見えていた。でも今は違う。」「どう違う？」「人がいる場所になった。」健はしばらく黙っていた。それから、「それなら、いい一年だったじゃないか」と言った。春は笑った。「うん。そうだね。」駅に着くと、春の電話が鳴った。母からだった。「もしもし？」「春、お正月は帰ってくるんでしょう？」「もちろん。もうすぐ帰るよ。」「待っています。」電話を切ったあと、春は青いノートをバッグに入れた。そして、駅のホームで小さく言った。「行ってきます。」健も笑って言った。「行ってらっしゃい。」電車が動き始めた。春は窓の外を見ながら、最初に覚えた言葉をもう一度思った。**会う。**人に会う。言葉に会う。新しい自分に会う。電車は夜の町を進んでいった。", "en": "", "focus": "", "sentences": [{"jp": "祭りのあと、春は一人で大学の屋上（おくじょう）へ行った。", "en": "After the festival, Spring went to the rooftop of the university by herself."}, {"jp": "町の向こうには山が見え、遠くには海も見えた。", "en": "Beyond the town, we could see mountains, and in the distance, we could see the sea."}, {"jp": "空は赤く、夕方の光がゆっくり消えていった。", "en": "The sky was red, and the evening light was slowly disappearing."}, {"jp": "青いノートを開くと、今までのページが全部一つの話になっていた。", "en": "When I opened the blue notebook, all the previous pages were one story."}, {"jp": "「会う。", "en": "koko yori sekai ni itami o"}, {"jp": "話す。", "en": "."}, {"jp": "助ける。", "en": "Save them."}, {"jp": "失敗する。", "en": "Fail. "}, {"jp": "考える。", "en": "THINK"}, {"jp": "続ける。", "en": "Continue."}, {"jp": "そして、帰る。」", "en": "And then I'm going home. \""}, {"jp": "」春は考えた。", "en": "\"I thought about spring."}, {"jp": "「帰るというのは、ただ家へ戻ることではないのかもしれない。」", "en": "“Going home may not be just about going home.”"}, {"jp": "」新しい場所へ出て、知らない人に会い、違う考え方を知り、失敗して、それでも前へ進む。", "en": "\"Go to a new place, meet strangers, learn a different way of thinking, fail, and still move forward."}, {"jp": "そのあとで、自分が大切にしている場所へ戻る。", "en": "After that, go back to the place you cherish."}, {"jp": "そういうことも「帰る」と言ってもいいのだろう。", "en": "You can also say \"go home\"."}, {"jp": "健が屋上へ来た。", "en": "Ken came to the rooftop."}, {"jp": "「ここにいたのか。", "en": "Hey there."}, {"jp": "みんな春を探しているよ。」", "en": "Everyone is looking for spring. \""}, {"jp": "」「そうなの？」", "en": "\"Is that right?\""}, {"jp": "」「うん。", "en": "Yes. "}, {"jp": "もう帰ろう。」", "en": "- Let's just go home. - No, we're not going home."}, {"jp": "」春はノートを閉じた。", "en": "Spring closed her notebook."}, {"jp": "「健。", "en": "Ken"}, {"jp": "ありがとう。", "en": "Thank you."}, {"jp": "君に会えてよかった。」", "en": ""}, {"jp": "」「何だよ、急に。」", "en": ""}, {"jp": "」「この一年で、いろいろなことを学んだから。」", "en": ""}, {"jp": "」二人はエレベーターで下へ行き、大学の出口を通った。", "en": ""}, {"jp": "外では学生たちが話したり笑ったりしていた。", "en": ""}, {"jp": "通りには店の明かりがつき始め、駅へ向かう人が増えていた。", "en": ""}, {"jp": "春は立ち止まった。", "en": ""}, {"jp": "「最初の日、この場所がただの新しい町に見えていた。", "en": ""}, {"jp": "でも今は違う。」", "en": "But now we're very close."}, {"jp": "」「どう違う？」", "en": "- What terms do you think in?"}, {"jp": "」「人がいる場所になった。」", "en": "\"It has become a place where people are.\""}, {"jp": "」健はしばらく黙っていた。", "en": "Ken was silent for a while."}, {"jp": "それから、「それなら、いい一年だったじゃないか」と言った。", "en": "Then he said, \"Well then, it's been a good year.\""}, {"jp": "春は笑った。", "en": "Spring laughed."}, {"jp": "「うん。", "en": "\"Yup. "}, {"jp": "そうだね。」", "en": "Okay, um..."}, {"jp": "」駅に着くと、春の電話が鳴った。", "en": "When I arrived at the station, the phone rang in the spring."}, {"jp": "母からだった。", "en": "It was from my mother."}, {"jp": "「もしもし？」", "en": "“….Hello?”"}, {"jp": "」「春、お正月は帰ってくるんでしょう？」", "en": "\"Spring, the New Year is coming back, right?\""}, {"jp": "」「もちろん。", "en": "Of course."}, {"jp": "もうすぐ帰るよ。」", "en": "I'll be back soon. \""}, {"jp": "」「待っています。」", "en": "AWAITING"}, {"jp": "」電話を切ったあと、春は青いノートをバッグに入れた。", "en": "\"After hanging up, Spring put a blue notebook in her bag."}, {"jp": "そして、駅のホームで小さく言った。", "en": "And he said in a small voice on the platform of the station."}, {"jp": "「行ってきます。」", "en": "Then, we'll be going!\" "}, {"jp": "」健も笑って言った。", "en": "Ken also laughed and said."}, {"jp": "「行ってらっしゃい。」", "en": "Have a safe trip♡ "}, {"jp": "」電車が動き始めた。", "en": "\"The train started to move."}, {"jp": "春は窓の外を見ながら、最初に覚えた言葉をもう一度思った。", "en": "Spring looked out the window and thought again of the first words she had learned."}, {"jp": "**会う。", "en": "koko yori sekai ni itami o"}, {"jp": "**人に会う。", "en": "Meeting people."}, {"jp": "言葉に会う。", "en": "Meet with the words."}, {"jp": "新しい自分に会う。", "en": "Meet your new self."}, {"jp": "電車は夜の町を進んでいった。", "en": "The train traveled through the town at night."}]}];